# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, J, C, R = "Hélène", "Julien", "Chloé", "Camille"
D = [
(None, "Mardi 25 mai, 9 h 15. Une camionnette blanche s'est garée devant le Comptoir. Deux techniciens déchargent des projecteurs. Camille Rivière, la journaliste, serre la main de Julien.", "5월 25일 화요일 오전 9시 15분. 흰색 밴이 가게 앞에 섰다. 기술 스태프 두 명이 조명을 내린다. 기자 카미유 리비에르가 쥘리앵과 악수한다."),
(R, "Bonjour, Camille Rivière, de « France Cuisine ». Merci de nous accueillir.", "안녕하세요, 프랑스 퀴진의 카미유 리비에르입니다. 받아 주셔서 감사해요."),
(J, "Bonjour, madame. Julien Benali, le directeur de salle. Je vous en prie, entrez.", "안녕하세요. 홀 책임자 쥘리앵 브날리입니다. 어서 들어오세요."),
(R, "Vous êtes très organisés. Mon équipe a l'habitude de trouver le chaos.", "아주 정돈돼 있네요. 저희 팀은 보통 난장판을 만나는 데 익숙해요."),
(J, "Le chaos, c'est pour après le service. Là, on respecte la caméra.", "난장판은 서비스 끝난 뒤 몫이에요. 지금은 카메라를 모십니다."),
(R, "Où est la cheffe ? Je voudrais la saluer avant de commencer.", "셰프님은 어디 계세요? 시작 전에 인사드리고 싶은데요."),
(J, "En cuisine. Elle fait semblant d'être calme. Elle a le trac depuis hier.", "주방에요. 침착한 척하고 계세요. 어제부터 떨고 계시거든요."),
(H, "Je t'entends, Julien. Bonjour, madame. Excusez la tenue, je sors du four.", "다 들려, 쥘리앵. 안녕하세요. 옷차림은 이해해 주세요, 오븐에서 막 나왔거든요."),
(R, "Vous êtes parfaite. Les téléspectateurs adorent les vraies cuisines.", "완벽하세요. 시청자들은 진짜 주방을 좋아하거든요."),
(H, "Merci. Mais je préviens : je ne suis pas à l'aise devant une caméra.", "고맙습니다. 그런데 미리 말해 둘게요. 카메라 앞에서는 영 불편해요."),
(R, "Personne ne l'est au début. On va y aller doucement, et on peut refaire.", "처음엔 다들 그래요. 천천히 갈 거고, 다시 찍어도 돼요."),
(C, "Bonjour ! Je suis Chloé. Vous voulez un café avant de tourner ?", "안녕하세요! 클로에예요. 촬영 전에 커피 드릴까요?"),
(R, "Volontiers. Et vous, vous apparaissez dans le reportage ?", "그러죠. 그리고 클로에 씨도 방송에 나오나요?"),
(C, "Moi ? Oh non, je suis juste la stagiaire. Enfin, l'apprentie.", "저요? 아니에요, 그냥 실습생이에요. 아, 견습생이요."),
(J, "Elle fait partie de la maison. Elle a droit à son plan, comme nous.", "가족 같은 직원이에요. 우리처럼 자기 컷이 나올 자격이 있죠."),
(R, "Un plan ? Vous connaissez le vocabulaire, vous ?", "컷 말이죠? 용어를 아시네요?"),
(J, "J'ai regardé des vidéos hier soir. Je suis un homme préparé.", "어젯밤 영상을 찾아봤어요. 준비된 남자거든요."),
(R, "Alors je vous explique la règle d'or : quand je dis « silence », plus un mot.", "그럼 황금률을 알려 드릴게요. 제가 « 정숙 » 이라고 하면 한마디도 안 돼요."),
(H, "Même les casseroles ?", "냄비 소리도요?"),
(R, "Surtout les casseroles. Le son, c'est la moitié de l'image.", "특히 냄비요. 소리가 영상의 절반이거든요."),
(None, "Le preneur de son fixe un micro-cravate sur le col d'Hélène. Elle se raidit.", "음향 담당이 엘렌의 옷깃에 핀마이크를 단다. 엘렌이 몸을 굳힌다."),
(H, "Je dois parler normalement ? Ou plus fort ?", "평소처럼 말하면 돼요? 아니면 더 크게요?"),
(R, "Comme si vous parliez à un client. Oubliez la caméra.", "손님한테 말하듯이요. 카메라는 잊으세요."),
(H, "Facile à dire. Elle est énorme, cette caméra.", "말은 쉽죠. 저 카메라 엄청 크네요."),
(J, "Regarde Camille, pas l'objectif. Camille, c'est comme une cliente.", "카메라 말고 카미유 씨를 봐. 손님이라고 생각해."),
(R, "Exactement. Prête ? Silence, ça tourne.", "맞아요. 준비됐나요? 정숙, 촬영 들어갑니다."),
(R, "Hélène Marchand, vous avez repris ce restaurant il y a quatre ans. Pourquoi ?", "엘렌 마르샹 씨, 4년 전에 이 식당을 이어받으셨죠. 왜 그러셨어요?"),
(H, "Parce que... c'était la maison de ma mère. Et puis j'avais envie de revenir.", "그게... 어머니의 가게였으니까요. 그리고 돌아오고 싶었어요."),
(R, "Coupez. Hélène, vous regardez trop vers le sol. On refait ?", "컷. 엘렌, 바닥을 너무 보세요. 다시 갈까요?"),
(H, "Pardon. Je recommence. Je regarde vers vous.", "죄송해요. 다시 할게요. 카미유 씨를 볼게요."),
(R, "Ça tourne. Pourquoi avoir repris ce restaurant ?", "촬영합니다. 왜 이 식당을 이어받으셨죠?"),
(H, "Parce que c'était la maison de ma mère. Et j'avais envie de la faire revivre.", "어머니의 가게였으니까요. 그리고 다시 살려 내고 싶었어요."),
(R, "Très bien. Vous avez failli tout perdre, il y a sept mois. Que s'est-il passé ?", "아주 좋아요. 1년 반 전에는 모든 걸 잃을 뻔하셨죠. 무슨 일이 있었나요?"),
(H, "Un enchaînement de coups durs. Un loyer plus lourd, un contrôle sanitaire, des dettes.", "나쁜 일이 연달아 터졌어요. 더 무거운 월세, 위생 검사, 빚."),
(R, "Et comment avez-vous tenu ?", "어떻게 버텨 내셨나요?"),
(H, "Pas toute seule. Mon père, mon équipe, et nos clients.", "혼자서는 아니었어요. 아버지, 직원들, 그리고 손님들 덕분이었죠."),
(J, "Pardon, je vais éternuer. Mille excuses.", "죄송해요, 재채기가 나려고 해요. 정말 미안합니다."),
(R, "Coupez ! Julien, on est à quinze secondes de l'émotion, là.", "컷! 쥘리앵, 지금 감정이 올라오기 15초 전이었어요."),
(J, "Désolé. Mon nez a un sens du timing catastrophique.", "미안해요. 제 코는 타이밍 감각이 최악이네요."),
(H, "Ça m'a fait du bien de rire. Je suis moins crispée.", "웃고 나니 한결 낫네요. 덜 긴장돼요."),
(R, "Voilà. C'est tout l'art de l'interview : faire oublier la caméra.", "그게 바로 인터뷰의 기술이에요. 카메라를 잊게 만드는 거죠."),
(R, "On reprend à la question sur la solidarité. Silence, ça tourne.", "연대 질문부터 다시 갑니다. 정숙, 촬영."),
(R, "Vous avez lancé un financement participatif. Trente jours, quarante mille euros. Vous y croyiez ?", "크라우드펀딩을 하셨죠. 30일에 4만 유로. 되리라 믿으셨나요?"),
(H, "Honnêtement ? Non. J'étais certaine que ça ne marcherait pas.", "솔직히요? 아니요. 안 될 거라고 확신했어요."),
(R, "Et pourtant, vous avez récolté combien ?", "그런데도 얼마를 모으셨죠?"),
(H, "Quarante-trois mille huit cent soixante-dix euros. Mille deux cent trente-sept donateurs.", "4만 3,870유로요. 후원자는 1,237명이었고요."),
(R, "Quel sentiment ça vous a laissé ?", "그때 어떤 기분이 드셨나요?"),
(H, "De la gratitude. Et une grande responsabilité aussi.", "고마움이요. 그리고 큰 책임감도요."),
(R, "Superbe. Julien, à vous maintenant. Que dites-vous aux clients qui hésitent à entrer ?", "아주 좋아요. 이제 쥘리앵 씨 차례. 들어올까 망설이는 손님께는 뭐라고 하시나요?"),
(J, "Je leur dis : entrez, la porte n'est pas fermée à clef, et le plat du jour est généreux.", "이렇게 말해요. 들어오세요, 문은 안 잠겼고 오늘의 요리 양도 넉넉하다고요."),
(R, "Vous êtes drôle. Pour la caméra, vous pouvez le répéter plus lentement ?", "재밌으시네요. 카메라를 위해 조금 천천히 다시 말해 주실래요?"),
(J, "Évidemment. Entrez. La porte est ouverte. Le plat du jour est généreux.", "물론이죠. 들어오세요. 문은 열려 있어요. 오늘의 요리는 양이 넉넉합니다."),
(R, "Vous êtes associé depuis peu, c'est bien ça ?", "얼마 전에 동업자가 되셨다고요, 맞죠?"),
(J, "Depuis deux semaines. Vingt pour cent du capital, cent pour cent du trac.", "2주 됐어요. 지분은 20퍼센트인데 긴장은 100퍼센트죠."),
(R, "Qu'est-ce que ça change au quotidien ?", "일상에서 무엇이 달라졌나요?"),
(J, "Rien dans mes gestes. Tout dans ma tête : chaque verre cassé, c'est un peu mon argent.", "행동은 그대로예요. 달라진 건 머릿속이죠. 깨진 잔 하나가 이제 내 돈이거든요."),
(R, "Parfait. Je vous demande aussi un plan de coupe en salle. Vous pouvez servir normalement ?", "홀 보충 컷도 필요해요. 평소처럼 서빙해 주실 수 있을까요?"),
(J, "Chloé, tu portes deux assiettes à la table quatre. Pas d'acrobaties.", "클로에, 4번 테이블에 접시 두 개 갖다줘. 곡예는 하지 말고."),
(C, "Moi ? À la caméra ? Je vais renverser le plat, c'est sûr !", "저요? 카메라 앞에서요? 분명 쏟을 거예요!"),
(R, "Si vous renversez, on coupe et on recommence. Aucun drame.", "쏟으면 끊고 다시 하면 돼요. 아무 문제 없어요."),
(C, "Ouf. Alors je me jette à l'eau.", "휴. 그럼 눈 딱 감고 해 볼게요."),
(None, "Chloé marche avec deux assiettes. La caméra la suit. Elle pose les plats sans un bruit.", "클로에가 접시 두 개를 들고 걷는다. 카메라가 따라간다. 소리 하나 없이 접시를 내려놓는다."),
(R, "Coupez ! C'était beau. Vous avez un talent naturel.", "컷! 멋졌어요. 타고난 재능이 있네요."),
(C, "C'est la peur qui m'a fait marcher droit.", "무서워서 똑바로 걸은 거예요."),
(R, "Et si je vous pose une question, face caméra ? Seulement trois phrases.", "카메라 앞에서 질문 하나 해도 될까요? 딱 세 문장이면 돼요."),
(C, "Trois phrases ? Je vais bégayer, je le sens.", "세 문장이요? 말을 더듬을 것 같아요."),
(H, "Respire. Parle comme tu parles à ton carnet.", "숨 쉬어. 수첩이랑 얘기하듯 말해."),
(R, "Chloé, qu'est-ce que le Comptoir de Marthe vous a appris ?", "클로에 씨, 마르트의 카운터에서 무엇을 배우셨나요?"),
(C, "Qu'on n'apprend pas qu'à cuisiner. On apprend à regarder les gens.", "요리만 배우는 게 아니라는 거요. 사람을 바라보는 법도 배우죠."),
(R, "Belle phrase. Vous l'aviez préparée ?", "멋진 말이네요. 준비해 둔 건가요?"),
(C, "Non, elle est sortie toute seule. Ça arrive quand on a peur.", "아니요, 저절로 나왔어요. 겁날 때 그런 일이 생기나 봐요."),
(None, "Pause. Un technicien change l'éclairage. Camille s'assoit au bar avec Hélène.", "휴식. 기술 스태프가 조명을 바꾼다. 카미유가 엘렌과 바에 나란히 앉는다."),
(R, "Hélène, avant la dernière séquence, une question hors micro. Je peux ?", "엘렌 씨, 마지막 촬영 전에 마이크 끄고 질문 하나 해도 될까요?"),
(H, "C'est « off », donc ? Je vous écoute.", "그럼 비공개인가요? 들어 볼게요."),
(R, "Je sais qu'en face, il y a un restaurant concurrent. Vous le détestez ?", "맞은편에 경쟁 식당이 있다고 들었어요. 싫어하세요?"),
(H, "Détester, non. Il y a eu des jalousies. Maintenant, on s'aide.", "싫어하진 않아요. 질투도 있었지만 지금은 서로 도와요."),
(R, "Voilà une nuance que j'aimerais garder à l'antenne, avec votre accord.", "그 뉘앙스는 허락해 주시면 방송에 담고 싶어요."),
(H, "D'accord, mais ne mettez pas son nom. Il doit rester libre.", "좋아요, 대신 이름은 빼 주세요. 그 사람도 자유로워야 하니까요."),
(R, "Promis. Je ne mets pas les pieds dans le plat.", "약속해요. 분위기 망치는 일은 하지 않을게요."),
(R, "Maintenant, la séquence cuisine. Vous pouvez dresser une blanquette, comme tous les jours ?", "이제 주방 컷이에요. 평소처럼 블랑케트를 담아 주실 수 있나요?"),
(H, "Bien sûr. Mais je dresse vite, vous allez devoir me suivre.", "물론이죠. 하지만 빨리 담으니까 따라오셔야 해요."),
(R, "On va s'adapter. Silence, ça tourne.", "맞춰 갈게요. 정숙, 촬영."),
(None, "Hélène dresse l'assiette en trente secondes. Le cadreur suit ses mains, très près.", "엘렌이 30초 만에 접시를 담는다. 카메라맨이 아주 가까이서 손을 따라간다."),
(R, "Coupez. Magnifique. On a eu une belle lumière sur la sauce.", "컷. 훌륭해요. 소스에 빛이 잘 받았어요."),
(H, "C'est donc ça, le vrai métier de la télé : la lumière sur la sauce.", "그러니까 그게 방송의 진짜 일이군요. 소스에 빛 맞추기."),
(R, "Un peu. Et surtout, la patience. On a tourné trois heures pour sept minutes.", "그런 편이죠. 그리고 무엇보다 인내심. 7분 분량을 위해 세 시간을 찍거든요."),
(J, "Sept minutes ? Avec une heure de rires coupés au montage ?", "7분이요? 한 시간 분량의 웃음은 편집에서 잘리고요?"),
(R, "Oui. Mais le montage garde souvent le meilleur, comme l'éternuement de Julien.", "네. 그래도 편집에서는 보통 최고 장면이 남죠. 쥘리앵 씨 재채기처럼요."),
(J, "Non ! Madame, je vous en supplie, pas l'éternuement.", "안 돼요! 부탁드립니다, 재채기는 빼 주세요."),
(R, "Je plaisante. Mais peut-être qu'on le garde dans le bêtisier.", "농담이에요. 대신 NG 모음에는 넣을지도 몰라요."),
(H, "Quand est-ce que ça passe, exactement ?", "방송은 정확히 언제 나가나요?"),
(R, "Le jeudi dix juin, dans le magazine du soir. Je vous enverrai un lien.", "6월 10일 목요일 저녁 매거진 프로그램이에요. 링크 보내 드릴게요."),
(C, "À la télé, vraiment ? Ma grand-mère va pleurer.", "텔레비전에, 진짜로요? 할머니가 우시겠어요."),
(J, "Il faudra réserver une table pour toute la famille de Chloé.", "클로에네 온 가족 자리를 예약해 둬야겠네."),
(H, "On gardera la douze, au fond. Pour la discrétion.", "12번 안쪽 자리를 비워 두자. 조용히 있을 수 있게."),
(R, "Hélène, dernière question. Votre mot de la fin ?", "엘렌 씨, 마지막 질문이에요. 마무리 한마디 부탁드려요."),
(H, "Ici, on fait à manger comme on aimerait qu'on nous le fasse.", "여기선 우리가 대접받고 싶은 방식으로 요리해요."),
(R, "C'est parfait. Et si on la prononçait encore une fois, sans hésiter ?", "완벽해요. 한 번만 더, 망설이지 말고 해 볼까요?"),
(H, "Ici, on fait à manger comme on aimerait qu'on nous le fasse. Voilà.", "여기선 우리가 대접받고 싶은 방식으로 요리해요. 이게 전부예요."),
(R, "Coupez. C'est dans la boîte. Merci à toute l'équipe.", "컷. 촬영 끝이에요. 팀 전체에 감사드려요."),
(H, "Déjà ? J'ai eu l'impression que ça ne durait que dix minutes.", "벌써요? 십 분밖에 안 지난 것 같은데."),
(R, "C'est le signe que vous étiez dedans. Les vrais bons moments passent vite.", "그만큼 몰입하셨다는 뜻이에요. 진짜 좋은 순간은 빨리 지나가죠."),
(J, "Camille, vous restez déjeuner ? Table quatre, au calme.", "카미유 씨, 점심 드시고 가실래요? 4번 테이블, 조용한 자리예요."),
(R, "Avec plaisir. Mon équipe aussi, si ça ne dérange pas.", "기꺼이요. 팀원들도 괜찮을까요?"),
(H, "Ça ne dérange pas du tout. Qu'ils goûtent la blanquette qu'ils ont filmée.", "전혀요. 찍은 블랑케트를 직접 맛보시게 해야죠."),
(R, "Ah, ça, c'est la meilleure paie qu'on puisse avoir.", "아, 그건 우리가 받을 수 있는 최고의 보수네요."),
(C, "Je peux vous demander un truc, Camille ? C'est difficile, d'être journaliste télé ?", "카미유 씨, 하나 여쭤봐도 돼요? 방송 기자 일은 어려운가요?"),
(R, "Le plus dur, c'est d'écouter vraiment. Le reste vient après.", "가장 어려운 건 진짜로 듣는 거예요. 나머지는 그다음이죠."),
(C, "Je le note dans mon carnet : écouter vraiment. Et « plan de coupe ».", "수첩에 적어 둘게요. 진짜로 듣기. 그리고 « 보충 컷 » 도요."),
(J, "Ton carnet, c'est ton vrai journal de bord.", "네 수첩은 진짜 항해 일지네."),
(R, "Pour votre ouverture de midi, vous voulez qu'on filme les premiers clients ?", "점심 오픈 때 첫 손님들도 찍을까요?"),
(H, "Seulement s'ils sont d'accord. Je leur demande avant.", "손님들이 동의하실 때만요. 제가 먼저 여쭤볼게요."),
(R, "Bonne idée. On floutera ceux qui refusent, c'est la loi.", "좋은 생각이에요. 거절하는 분들은 모자이크 처리할게요, 법이니까요."),
(J, "Vous voyez ? Même la télé a des règles de savoir-vivre.", "보세요? 방송에도 예의범절이 있잖아요."),
(R, "Il le faut bien. Sans confiance, pas d'images, pas de reportage.", "그래야죠. 신뢰가 없으면 영상도, 보도도 없으니까요."),
(C, "Et si la caméra montre un trou dans mon tablier ?", "카메라에 앞치마 구멍이 나오면 어쩌죠?"),
(H, "Alors la France entière saura que tu travailles.", "그럼 프랑스 전체가 네가 일한다는 걸 알게 되겠지."),
(J, "Bienvenue chez les vedettes. Premier conseil : ne lis jamais les commentaires.", "스타의 세계에 온 걸 환영해. 첫 번째 조언: 댓글은 절대 읽지 마."),
(C, "Même pas ceux de ma grand-mère ?", "할머니 댓글도요?"),
(R, "Surtout pas ceux-là. Elle écrira « bravo » en lettres majuscules.", "그건 더더욱이죠. 할머니는 « 브라보 » 를 대문자로 쓰실 거예요."),
(None, "Midi moins dix. Chloé prépare la salle. Le projecteur éclaire l'ardoise toute neuve : « Ici, tout est fait maison. »", "12시 10분 전. 클로에가 홀을 준비한다. 조명이 새 칠판을 비춘다. « 여기선 모든 게 수제입니다. »"),
(C, "Hélène, on peut garder le projecteur sur l'ardoise ? Elle est tellement belle comme ça.", "엘렌, 조명을 칠판에 계속 비춰 둬도 돼요? 이렇게 보니 정말 예뻐요."),
(H, "Non, ma chérie. Demain, on revient à la vraie lumière.", "아니, 우리 클로에. 내일은 진짜 조명으로 돌아가는 거야."),
(J, "Oui, la lumière du mardi, celle qui montre aussi les taches sur la nappe.", "맞아요, 화요일의 빛이죠. 식탁보 얼룩까지 비추는 그 빛."),
(R, "Les taches, on ne les montre jamais. C'est le secret de la télévision.", "얼룩은 절대 안 보여요. 그게 방송의 비밀이죠."),
(H, "Chloé, au service. Camille, installez-vous. Silence... ça mijote.", "클로에, 서비스 시작이야. 카미유 씨, 앉으세요. 정숙... 지금 끓고 있어요."),
]

